/**
 * 路径比较的**分隔符归一化**：判据本体，只有纯函数。
 *
 * ── 为什么需要这一处（一条在 Windows 上把 8 条"诚实红"变成假警报的缺陷）──
 * 本仓有一族"接线状态"断言：枚举 `packages/hub/src` 下的 .ts 文件，断言某个函数的调用方
 * 名单为空（或恰好等于某个已知集合），标题写着【今天成立】、注释写着【接上那天会红】。
 * 它们的取材用 `join()`（Windows 给出反斜杠），判据与期望值用正斜杠字面量，于是：
 *   · 过滤器 `f.endsWith("charter/store.ts")`、`f.includes("/charter/")` **永不命中**
 *     ⇒ 该排除的定义处没被排除；
 *   · 期望值 `SRC + "/harness/verifier.ts"` 拼出 `…\src/harness/verifier.ts`，
 *     与实到的 `…\src\harness\verifier.ts` **永不相等**。
 * 两侧同时失效 ⇒ 这 8 发在 Windows 上恒红，而红的成因是**分隔符**，不是它们声称的
 * 「接线缺口」。后果不只是难看：一条恒红的断言没有分辨力，接线真的发生时它不会
 * 给出任何**新的**信号 —— 而这正是这些断言存在的全部理由（0014 §3 / 0015 §3 钉的
 * 就是"接线那天要有人来改文档"）。
 *
 * ── 为什么归一化在**取材侧**而不是期望侧 ──────────────────────────
 * 反过来（把期望值换成 `join()` 拼出来的本地分隔符形状）也能让这 8 发红→绿，
 * 而那是**错的修法**，两个理由：
 *  ① 断言文案、决策文档、以及 `docs/INDEX.md` 里那些名单全是正斜杠形状；换成
 *     本地分隔符等于把「这条断言在说什么」系到跑它的那台机器的 OS 上。
 *  ② 更要紧的是**失效方向**：正斜杠期望 + 归一化取材 ⇒ 分隔符出问题时两侧一起错，
 *     名单变长 ⇒ 红（有人来看）。`join()` 期望 ⇒ 有人在 macOS/Linux 上写新断言时
 *     期望值里手写一个反斜杠，两侧一起"对"地错 ⇒ 名单少一项 ⇒ **绿**。
 *     这一族断言不能承受的是少算（0014 §3、本仓记过多次的「把真生产者判成零」）。
 *
 * ── 已知边界（不假装全覆盖）────────────────────────────────────
 * 只归一化**反斜杠 → 正斜杠**这一条映射。它覆盖 Windows；不处理大小写不敏感
 * （NTFS 上 `Src` 与 `src` 是同目录）—— 本仓所有比较用的字面量都由 `join()` 或
 * 正斜杠常量而来，没有手写大小写变体的通路，所以那一维今天是空的。
 * UNC 前缀（`\\server\share`）归一化后变成 `//server/share`，本仓不产生这种路径
 * （夹具锚 `import.meta.url`，见 fixture-dir.ts 文件头同一理由）。
 */

const BACKSLASH: string = String.fromCharCode(92);

/**
 * 把原生路径转成正斜杠形状。**只做字符串替换，不做语义解析** ——
 * 它不是 `path.posix.normalize`，不会折叠 `..`，也不会改相对/绝对形态。
 */
export function toPosix(p: string): string {
  return p.split(BACKSLASH).join("/");
}

/**
 * 归一化后的**仓库相对路径**（用于报错文案与名单断言）。
 *
 * `base` 这里**也**过一次 `toPosix()`，而不是要求调用方先归一化。理由是一次实测：
 * 第一版写成"base 必须已归一化"，而同文件的用例立刻造出了反例 —— 调用方手里
 * 同时握着 `join()` 出来的原生 base 与正斜杠的 file 是**常态**（那 8 发的成因就是
 * 这两种形状混用）。要求"先归一化"是一条只能靠自觉的约束，忘了的后果是
 * **静默不剥**：名单里留下的不是"错的名字"而是**整条绝对路径**，
 * 于是断言仍然会红（方向安全），但红成"路径拼错了"那种看不出所以然的样子。
 */
export function relPosix(p: string, base: string): string {
  const pos = toPosix(p);
  const b = toPosix(base);
  return pos.startsWith(b + "/") ? pos.slice(b.length + 1) : pos;
}

/**
 * 拼一条**可用于比较与断言**的正斜杠路径。
 *
 * 存在的全部理由：期望值不能写 `SRC + "/x/y.ts"` —— 那在 Windows 上是一条
 * `…\src/x/y.ts`，看着像路径而永远比不中。给段就一次拼对，比让每个文件自己
 * 记"这里要 toPosix"要便宜（本仓那条「同一判据不许有两份字面写法」的规矩，
 * 0026 §0 为 `kindOf()` 立的那一条，在这里同样成立）。
 */
export function posixJoin(base: string, ...segs: string[]): string {
  return [toPosix(base), ...segs].join("/");
}
